import{_ as t,o as a,c as o,a0 as l}from"./chunks/framework.Bkgi-hoF.js";const g=JSON.parse('{"title":"Percentage Rollouts","description":"","frontmatter":{},"headers":[],"relativePath":"features/rollouts.md","filePath":"features/rollouts.md"}'),r={name:"features/rollouts.md"};function i(s,e,n,u,d,h){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="percentage-rollouts" tabindex="-1">Percentage Rollouts <a class="header-anchor" href="#percentage-rollouts" aria-label="Permalink to &quot;Percentage Rollouts&quot;">​</a></h1><p>Gradually release features to a percentage of users. Start with 5%, validate, then increase to 20%, 50%, and finally 100%.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>Set a <strong>rollout percentage</strong> (0–100) on any config</li><li>Set the <strong>rollout value</strong> (what users in the rollout get)</li><li>Users are bucketed deterministically: same user always gets the same result</li></ol><h2 id="deterministic-bucketing" tabindex="-1">Deterministic Bucketing <a class="header-anchor" href="#deterministic-bucketing" aria-label="Permalink to &quot;Deterministic Bucketing&quot;">​</a></h2><p>Rollouts use a MurmurHash3 algorithm: <code>hash(flagKey + &quot;:&quot; + userId) % 100</code>. This means:</p><ul><li>The same user always gets the same bucket for a given flag</li><li>Different flags give the same user different buckets (independent rollouts)</li><li>No session storage or cookies required — purely based on userId</li></ul><h2 id="setting-up-a-rollout" tabindex="-1">Setting Up a Rollout <a class="header-anchor" href="#setting-up-a-rollout" aria-label="Permalink to &quot;Setting Up a Rollout&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Rollout</strong> section</li><li>Set the percentage (e.g., 20)</li><li>Set the rollout value (e.g., <code>true</code> for a boolean flag)</li><li>Save</li></ol><h2 id="rollout-targeting" tabindex="-1">Rollout + Targeting <a class="header-anchor" href="#rollout-targeting" aria-label="Permalink to &quot;Rollout + Targeting&quot;">​</a></h2><p>Targeting rules have higher priority than rollouts in the evaluation pipeline. If a targeting rule matches, the rollout is skipped. This means you can:</p><ul><li>Target &quot;Enterprise Users&quot; → always get the feature</li><li>Roll out to 20% of everyone else → gradual release</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A <code>userId</code> must be provided in the SDK context for rollout to work</li><li>Without a userId, rollout is skipped and the default value is returned</li><li>The userId should be stable (don&#39;t use random session IDs)</li></ul><h2 id="consistency-across-modes" tabindex="-1">Consistency Across Modes <a class="header-anchor" href="#consistency-across-modes" aria-label="Permalink to &quot;Consistency Across Modes&quot;">​</a></h2><p>The same hashing algorithm is used in both server-side evaluation (client keys) and client-side evaluation (server keys). A user bucketed at 30% in one mode will be bucketed at 30% in the other — no flip-flopping during migration.</p>',16)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
